#[test]
fn test_signed_reads_take_the_high_bit_as_a_sign() {
    crate::testport::assert_eq(by_i8(&crate::testport::hex_blob("7f 80 ff")[..], 0), 127, "0x7f");
    crate::testport::assert_eq(by_i8(&crate::testport::hex_blob("7f 80 ff")[..], 1), -128, "0x80");
    crate::testport::assert_eq(by_i8(&crate::testport::hex_blob("7f 80 ff")[..], 2), -1, "0xff");
    crate::testport::assert_eq(by_i16(&crate::testport::hex_blob("7f ff 80 00 ff fe")[..], 0), 32767, "be 7fff");
    crate::testport::assert_eq(by_i16(&crate::testport::hex_blob("7f ff 80 00 ff fe")[..], 2), -32768, "be 8000");
    crate::testport::assert_eq(by_i16(&crate::testport::hex_blob("7f ff 80 00 ff fe")[..], 4), -2, "be fffe");
    crate::testport::assert_eq(by_i16le(&crate::testport::hex_blob("ff 7f 00 80 fe ff")[..], 0), 32767, "le 7fff");
    crate::testport::assert_eq(by_i16le(&crate::testport::hex_blob("ff 7f 00 80 fe ff")[..], 2), -32768, "le 8000");
    crate::testport::assert_eq(by_i16le(&crate::testport::hex_blob("ff 7f 00 80 fe ff")[..], 4), -2, "le fffe");
}
