#[test]
fn test_unsigned_32_bit_widens_without_going_negative() {
    crate::testport::assert_eq64(by_u32_64(&crate::testport::hex_blob("ff ff ff ff")[..], 0), 4294967295, "be ffffffff");
    crate::testport::assert_eq64(by_u32_64(&crate::testport::hex_blob("80 00 00 00")[..], 0), 2147483648, "be 80000000");
    crate::testport::assert_eq64(by_u32_64(&crate::testport::hex_blob("00 00 01 00")[..], 0), 256, "be 00000100");
    crate::testport::assert_eq64(by_u32le_64(&crate::testport::hex_blob("ff ff ff ff")[..], 0), 4294967295, "le ffffffff");
    crate::testport::assert_eq64(by_u32le_64(&crate::testport::hex_blob("00 00 00 80")[..], 0), 2147483648, "le 80000000");
    crate::testport::assert_eq64(by_u32le_64(&crate::testport::hex_blob("00 01 00 00")[..], 0), 256, "le 00000100");
}
#[test]
fn test_bounds_questions_do_not_read_out_of_range() {
    crate::testport::assert_eq(by_in(&crate::testport::hex_blob("00 01 02")[..], 0, 3), 1, "the whole blob");
    crate::testport::assert_eq(by_in(&crate::testport::hex_blob("00 01 02")[..], 1, 3), 0, "one past the end");
    crate::testport::assert_eq(by_in(&crate::testport::hex_blob("00 01 02")[..], 3, 0), 1, "an empty read at the end");
    crate::testport::assert_eq(by_in(&crate::testport::hex_blob("00 01 02")[..], 4, 0), 0, "an empty read past the end");
    crate::testport::assert_eq(by_in(&crate::testport::hex_blob("00 01 02")[..], -1, 1), 0, "a negative index");
    crate::testport::assert_eq(by_in(&crate::testport::hex_blob("00 01 02")[..], 1, -1), 0, "a negative count");
    crate::testport::assert_eq(by_in(&crate::testport::hex_blob("00 01 02")[..], 1, 2147483647), 0, "a count that would wrap i + n");
}
#[test]
fn test_reads_with_a_default_answer_it_off_the_end() {
    crate::testport::assert_eq(by_u8_or(&crate::testport::hex_blob("0a")[..], 0, -1), 10, "in range");
    crate::testport::assert_eq(by_u8_or(&crate::testport::hex_blob("0a")[..], 1, -1), -1, "one past");
    crate::testport::assert_eq(by_u16_or(&crate::testport::hex_blob("01 02")[..], 0, -1), 258, "u16 in range");
    crate::testport::assert_eq(by_u16_or(&crate::testport::hex_blob("01 02")[..], 1, -1), -1, "u16 straddling the end");
    crate::testport::assert_eq(by_u32_or(&crate::testport::hex_blob("ff ff ff ff")[..], 0, 7), -1, "u32 pattern");
    crate::testport::assert_eq(by_u32_or(&crate::testport::hex_blob("ff ff ff")[..], 0, 7), 7, "u32 short");
}
#[test]
fn test_searching_forwards_and_backwards() {
    crate::testport::assert_eq(by_find(&crate::testport::text_blob("abcabcab")[..], 0, &crate::testport::text_blob("abc")[..]), 0, "first");
    crate::testport::assert_eq(by_find(&crate::testport::text_blob("abcabcab")[..], 1, &crate::testport::text_blob("abc")[..]), 3, "from 1");
    crate::testport::assert_eq(by_find(&crate::testport::text_blob("abcabcab")[..], 4, &crate::testport::text_blob("abc")[..]), -1, "none after 4");
    crate::testport::assert_eq(by_find(&crate::testport::text_blob("abcabcab")[..], -5, &crate::testport::text_blob("cab")[..]), 2, "negative from is 0");
    crate::testport::assert_eq(by_find(&crate::testport::text_blob("abc")[..], 0, &crate::testport::text_blob("abcd")[..]), -1, "needle longer than hay");
    crate::testport::assert_eq(by_find(&crate::testport::text_blob("abc")[..], 3, &crate::testport::text_blob("")[..]), 3, "empty needle at end");
    crate::testport::assert_eq(by_find_back(&crate::testport::text_blob("abcabcab")[..], 100, &crate::testport::text_blob("abc")[..]), 3, "last");
    crate::testport::assert_eq(by_find_back(&crate::testport::text_blob("abcabcab")[..], 2, &crate::testport::text_blob("abc")[..]), 0, "last at or before 2");
    crate::testport::assert_eq(by_find_back(&crate::testport::text_blob("abcabcab")[..], 100, &crate::testport::text_blob("zz")[..]), -1, "absent");
    crate::testport::assert_eq(by_match_at(&crate::testport::text_blob("abcabc")[..], 3, &crate::testport::text_blob("abc")[..]), 1, "match at");
    crate::testport::assert_eq(by_match_at(&crate::testport::text_blob("abcabc")[..], 4, &crate::testport::text_blob("abc")[..]), 0, "match runs off the end");
}
